INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q759986', 'Sokehs Rebellion', 'The Sokehs rebellion was an uprising of the Sokehs tribe against local German rule that started on Sokehs Island off the main island of Pohnpei in the Eastern Caroline Islands (presently the Federated States of Micronesia) in 1910/1911. The German district commissioner, Gustav Boeder, three other German officials and five islanders were killed by the rebels before Imperial German Navy units arrived and restored order.', 1910, 10, 18, 1911, 2, 23, 'day', '18 October 1910 – 23 February 1911', 34, 'https://en.wikipedia.org/wiki/Sokehs_rebellion'),
  ('Q2478583', 'Compact of Free Association', 'The Compacts of Free Association (COFA) are international agreements establishing and governing the relationships of free association between the United States and the three Pacific Island sovereign states: Federated States of Micronesia (FSM), the Republic of the Marshall Islands (RMI), and the Republic of Palau. As a result, these countries are sometimes known as the Freely Associated States (FASs).', 1980, NULL, NULL, NULL, NULL, NULL, 'decade', '1980s', 60, 'https://en.wikipedia.org/wiki/Compact_of_Free_Association'),
